import{_ as n,o as e,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Chuyển Đổi Nghiệp Vụ: Hỗ Trợ Agency Cá Nhân (Personal / Solo Creator Mode)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/personal-agency-transition/README.md","filePath":"feature/agency-workspace/personal-agency-transition/README.md"}'),o={name:"feature/agency-workspace/personal-agency-transition/README.md"};function h(c,t,r,l,g,s){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="chuyen-đoi-nghiep-vu-ho-tro-agency-ca-nhan-personal-solo-creator-mode" tabindex="-1">Chuyển Đổi Nghiệp Vụ: Hỗ Trợ Agency Cá Nhân (Personal / Solo Creator Mode) <a class="header-anchor" href="#chuyen-đoi-nghiep-vu-ho-tro-agency-ca-nhan-personal-solo-creator-mode" aria-label="Permalink to &quot;Chuyển Đổi Nghiệp Vụ: Hỗ Trợ Agency Cá Nhân (Personal / Solo Creator Mode)&quot;">​</a></h1><h2 id="brandhub-—-technical-business-specification-index" tabindex="-1">BrandHub — Technical &amp; Business Specification Index <a class="header-anchor" href="#brandhub-—-technical-business-specification-index" aria-label="Permalink to &quot;BrandHub — Technical &amp; Business Specification Index&quot;">​</a></h2><p>Tài liệu này tổng hợp toàn bộ phân tích nghiệp vụ, kiến trúc kỹ thuật, thiết kế cơ sở dữ liệu và đặc tả giao diện cho tính năng: <strong>Cho phép người dùng tạo và sử dụng Agency cho mục đích Cá nhân (Solo Creator / Freelancer / Tự sản xuất và đăng bài), đồng thời tự động chuyển đổi thẳng vào không gian làm việc để sử dụng ngay mà không bị rào cản bởi quy trình quản lý khách hàng (Client Management) của Agency truyền thống.</strong></p><hr><h2 id="📂-danh-muc-tai-lieu-chi-tiet" tabindex="-1">📂 Danh Mục Tài Liệu Chi Tiết <a class="header-anchor" href="#📂-danh-muc-tai-lieu-chi-tiet" aria-label="Permalink to &quot;📂 Danh Mục Tài Liệu Chi Tiết&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">STT</th><th style="text-align:left;">Tài liệu</th><th style="text-align:left;">Nội dung chính</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>01</strong></td><td style="text-align:left;"><a href="./01_BUSINESS_REQUIREMENTS_AND_USER_FLOW.html">01_BUSINESS_REQUIREMENTS_AND_USER_FLOW.md</a></td><td style="text-align:left;">Phân tích bài toán, so sánh As-Is vs To-Be, User Journeys, Business Rules và Use Cases chi tiết cho Cá nhân vs Doanh nghiệp.</td></tr><tr><td style="text-align:center;"><strong>02</strong></td><td style="text-align:left;"><a href="./02_TECHNICAL_ARCHITECTURE_AND_DATA_FLOW.html">02_TECHNICAL_ARCHITECTURE_AND_DATA_FLOW.md</a></td><td style="text-align:left;">Kiến trúc luồng dữ liệu, Diagram tương tác PlantUML / Mermaid giữa FE - Gateway - Business Service - DB, API Contracts mở rộng.</td></tr><tr><td style="text-align:center;"><strong>03</strong></td><td style="text-align:left;"><a href="./03_DATABASE_SCHEMA_CHANGES.html">03_DATABASE_SCHEMA_CHANGES.md</a></td><td style="text-align:left;">Thiết kế Database, DDL Migration PostgreSQL (<code>agency_type</code> ENUM), kịch bản Auto-provisioning Workspace cá nhân, Entity Java &amp; DTO mapping.</td></tr><tr><td style="text-align:center;"><strong>04</strong></td><td style="text-align:left;"><a href="./04_UI_UX_AND_SCREEN_SPEC.html">04_UI_UX_AND_SCREEN_SPEC.md</a></td><td style="text-align:left;">Thiết kế màn hình Tạo Agency mới (lựa chọn mục đích), cơ chế Personal Mode trên Sidebar/Navigation (ẩn tính năng Client), luồng đăng bài không cần chờ duyệt.</td></tr><tr><td style="text-align:center;"><strong>05</strong></td><td style="text-align:left;"><a href="./05_IMPLEMENTATION_PLAN_AND_TASKS.html">05_IMPLEMENTATION_PLAN_AND_TASKS.md</a></td><td style="text-align:left;">Kế hoạch triển khai chi tiết qua 4 giai đoạn, phân rã đầu việc (Task breakdown) và tiêu chí kiểm thử (Acceptance Criteria).</td></tr></tbody></table><hr><h2 id="🎯-tom-tat-muc-tieu-cot-loi" tabindex="-1">🎯 Tóm Tắt Mục Tiêu Cốt Lõi <a class="header-anchor" href="#🎯-tom-tat-muc-tieu-cot-loi" aria-label="Permalink to &quot;🎯 Tóm Tắt Mục Tiêu Cốt Lõi&quot;">​</a></h2><ol><li><strong>Phân loại mục đích sử dụng ngay từ đầu</strong>: <ul><li><code>PERSONAL</code> (Cá nhân / Solo Creator): Người dùng tự sản xuất nội dung, kết nối kênh mạng xã hội và đăng bài cho chính thương hiệu của mình.</li><li><code>BUSINESS</code> (Doanh nghiệp / Agency truyền thông): Quản lý đội ngũ nhân sự, tạo workspace cho từng khách hàng, đàm phán gói truyền thông và gửi duyệt bài cho khách hàng.</li></ul></li><li><strong>Zero-friction Onboarding (&quot;Tạo xong dùng luôn&quot;)</strong>: <ul><li>Khi chọn <code>PERSONAL</code>, hệ thống tự động sinh 1 Workspace mặc định cá nhân (đồng bộ tên, logo, màu sắc) và gán quyền Quản trị (<code>MANAGER</code>).</li><li>Chuyển hướng người dùng thẳng vào không gian làm việc (<code>/workspaces/:id/dashboard</code> hoặc <code>/content-writing</code>) thay vì trang xem thông tin Agency rỗng.</li></ul></li><li><strong>Giao diện tinh gọn (Personal Workspace Mode)</strong>: <ul><li>Ẩn toàn bộ các menu dư thừa: Khách hàng, Hồ sơ khách hàng, Lời mời khách hàng, Cổng duyệt bài Portal, Phân quyền vai trò phức tạp.</li><li>Luồng viết bài cho phép Đăng ngay / Lên lịch trực tiếp mà không cần qua bước Chờ Client phê duyệt (<code>PENDING_CLIENT_APPROVAL</code>).</li></ul></li></ol>',9)])])}const _=n(o,[["render",h]]);export{u as __pageData,_ as default};
